        #[cfg(target_family = "windows")]
        assert_eq!(family(), Family::Windows);

        #[cfg(all(unix, not(target_family = "wasm")))]
        assert_eq!(family(), Family::Unix);
    }
}

//! Target-selection and the types shared by every backend.

